def _expand(widths: dict[tuple[float, float], list]) -> dict[str, tuple[float, float]]:
    out = {}
    for pair, spans in widths.items():
        for s in spans:
            if isinstance(s, int):
                out[chr(s)] = pair
            else:
                a, n = s
                for cp in range(a, a + n):
                    out[chr(cp)] = pair
    return out

CHAR_WIDTHS: dict[str, tuple[float, float]] = _expand(_WIDTHS)
